def max_volume(s):
    if s < 3:
        return 0
    max_vol = 0
    for a in range(1, s - 1):
        for b in range(a, s - a):
            c = s - a - b
            if c >= b:
                vol = a * b * c
                if vol > max_vol:
                    max_vol = vol
    return max_vol
