def pancake_sort(arr):
    def flip(arr, i):
        left, right = 0, i
        while left < right:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

    n = len(arr)
    for size in range(n, 0, -1):
        max_index = 0
        for i in range(1, size):
            if arr[i] > arr[max_index]:
                max_index = i
        if max_index != size - 1:
            flip(arr, max_index)
            flip(arr, size - 1)
    return arr

